550	\section{Generalized Pauli observables}
551	% Paper label sec:generalized-pauli kept for cross-reference fidelity.
552	\label{sec:generalized-pauli}
553	
554	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
555		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
556		\lean{MIPStarRE.QPBT.primeTauObservable}
557		\uses{def:subfield-trace, def:lin-reg}
558		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
559		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
560		\begin{equation}\label{eq:pauli-fp}
561			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
562			\qquad \text{and} \qquad
563			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
564		\end{equation}
565		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
566		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
567		$\C^{\F_q}$
568		\[
569			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
570			\qquad \text{and} \qquad
571			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
572		\]
573		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
574		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
575		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
576		signs. All the $\tau^X$ operators commute with one another, as do all the
577		$\tau^Z$ operators. Their common eigenbases consist of the vectors
578		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
579		\[
580			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
581			\omega^{-\tr(ej)} \ket{j}\;, \qquad
582			\ket{e_Z} = \ket{e}\;;
583		\]
584		the Fourier transform
585		\begin{equation}\label{eq:fourier-f}
586			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
587			\omega^{-\tr(ab)} \ket{a}\bra{b}
588		\end{equation}
589		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
590		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
591		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
592		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
593		\[
594			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
595			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
596		\]
597			for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
598			The distinction between the general prime-characteristic definitions and
599			the characteristic-two specializations used by the Pauli basis test is
600			documented in \cite{gap:qpbt_characteristic-two-pauli-scope}.
601	\end{definition}
602	
603	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
604		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
605		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
606		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
607		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
608		\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
609		\lean{MIPStarRE.QPBT.primeTauObservable_X_mul_Z}
610		\leanok
611		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
612		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
613		\begin{enumerate}
614			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
615			      \begin{equation}\label{eq:pauli-product-power}
616				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
617				      \qquad \text{and} \qquad
618				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
619			      \end{equation}
620			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
621			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
622			      $p$-th roots of unity.
623			\item For all $a, b \in \F_q^n$,
624			      % Paper equation label kept on the display it names.
625			      \begin{equation}\label{eq:twisted-fq}
626				      \tau^X(a)\, \tau^Z(b)
627				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
628			      \end{equation}
629			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
630			      $q = p$, $n = 1$ reads
631			      \begin{equation}\label{eq:twisted-fp}
632				      \sigma^X(a)\, \sigma^Z(b)
633				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
634				      \qquad \text{for all } a, b \in \F_p\;.
635			      \end{equation}
636		\end{enumerate}
637	\end{lemma}
638	\begin{proof}
639		\uses{def:generalized-pauli, def:subfield-trace}
640		All identities are verified on computational basis states. For the product
641		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
642		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
643		combine by $\F_q$-linearity of the trace, and the power relation follows by
644		iterating. For the scalar twisted commutation,
645		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
646		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
647		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
648		follows by applying the scalar relation factor by factor and summing the
649		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
650		trace is the identity map, which gives \eqref{eq:twisted-fp}.
651	\end{proof}
652	
653	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
654		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
655		\leanok
656		\uses{def:dot-product-orthogonal, def:subfield-trace}
657		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
658		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
659		$v \notin V^\perp$,
660		\[
661			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
662		\]
663		where the expectation is over a uniformly random vector $\bu$ in $V$.
664	\end{lemma}
665	\begin{proof}
666		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
667		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
668		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
669		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
670		for the expectation, translation invariance of the uniform distribution on
671		$V$ gives
672		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
673		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
674		forces $C = 0$.
675	\end{proof}
676	
677	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
678		\uses{def:generalized-pauli, def:subfield-trace}
679		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
680		% Paper equation label kept on the display it names.
681		\begin{equation}\label{eq:pauli-obs-proj}
682			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
683		\end{equation}
684		and conversely
685			\begin{equation}\label{eq:pauli-inversion-0}
686			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
687			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
688			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
689				= \tau^W_b\;.
690			\end{equation}
691			The source scope and the binary specialization of these identities are
692			recorded in \cite{gap:qpbt_characteristic-two-pauli-scope}.
693	\end{lemma}
694	\begin{proof}
695		\uses{def:generalized-pauli, lem:cancellation}
696		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
697		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
698		definition, and for $W = X$ it follows from the single-qudit computation
699		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
700		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
701		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
702		substitute the first display and exchange the order of summation; by
703		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
704		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
705		it equals $1$.
706	\end{proof}
707	
708	Since only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the
709	maximally entangled state $\ket{\mathrm{EPR}_q}$ and the qudit Pauli
710	projectors are isomorphic to tensor products of qubit EPR states
711	$\ket{\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the
712	next lemma, which is what allows the Pauli basis test to self-test Pauli
713	observables and maximally entangled states over \emph{qubits}
714	(Chapter~\ref{chap:qpbt-test}).
715	
716	\begin{lemma}[Qudit-to-qubit isomorphism]\label{lem:pauli-binary}
717		\lean{MIPStarRE.QPBT.qubitPauliProj, MIPStarRE.QPBT.exists_qubitIsometry}
718		\leanok
719		\uses{def:admissible-size, def:subfields-kappa, def:binary-representation,
720			def:generalized-pauli, def:EPR}
721		For all admissible field sizes $q = 2^k$ and integers $L \ge 0$, there
722		exists an isomorphism $\phi : (\C^q)^{\ot L} \to (\C^2)^{\ot Lk}$ such that
723		\begin{equation}\label{eq:epr-q-to-epr-2}
724			\phi \ot \phi\, \ket{\mathrm{EPR}_q}^{\ot L}
725			= \ket{\mathrm{EPR}_2}^{\ot Lk}
726		\end{equation}
727		(applying the natural identifications between
728		$(\C^q)^{\ot L} \ot (\C^q)^{\ot L}$ and $(\C^q \ot \C^q)^{\ot L}$, and
729		between $(\C^2)^{\ot Lk} \ot (\C^2)^{\ot Lk}$ and
730		$(\C^2 \ot \C^2)^{\ot Lk}$). Moreover, for all $W \in \{X, Z\}$ and all
731		$u \in \F_q^L$,
732		\begin{equation}\label{eq:pauli-q-to-pauli-2}
733			\tau^W_u = \phi^\dagger\,
734			\Bigl(\bigotimes_{i=1}^L \bigotimes_{j=1}^k
735			\sigma^W_{u_{ij}}\Bigr)\, \phi\;.
736		\end{equation}
737		Here $(u_{ij})_{i,j}$ is the array of $\F_2$ values with
738		$u_i = \sum_j u_{ij} e_j$ for all $i \in \{1, \dots, L\}$, where
739		$\{e_1, \dots, e_k\}$ is the fixed self-dual normal basis of $\F_q$ over
740		$\F_2$ of Definition~\ref{def:binary-representation}; and for
741		$i \in \{1, \dots, L\}$ and $j \in \{1, \dots, k\}$ the $(i,j)$-th factor
742		$\sigma^W_{u_{ij}}$ denotes the projector
743		$\frac{1}{2}\bigl(\Id + (-1)^{u_{ij}} \sigma^W(1)\bigr)$ acting on the
744		$s$-th qubit, where $s = (i-1)k + j$.
745			We index the product coordinates from zero: values $(i-1,j-1)$ correspond to
746			the paper's pair $(i,j)$.  The corrected upper bound $j\leq k$ is
747			documented in \cite{gap:qpbt_pauli-binary-factor-index}.
748	\end{lemma}
749	\begin{proof}
750		\uses{lem:pauli-observable-expansion, lem:downsize_field,
751			lem:twisted-commutation}
752		Define the isometry $\theta : \C^q \to (\C^2)^{\ot k}$ by
753		$\theta\ket{a} = \ket{a_1} \ot \dots \ot \ket{a_k}$, where
754		$\kappa(a) = (a_1, \dots, a_k)$ is the binary representation with respect
755		to the fixed basis; since $\kappa$ is a bijection, $\theta$ is a unitary
756		and $\theta \ot \theta\, \ket{\mathrm{EPR}_{2^k}} =
757		\ket{\mathrm{EPR}_2}^{\ot k}$. For $a \in \F_q$ with
758		$\kappa(a) = (a_1, \dots, a_k)$, the inversion formula of
759		Lemma~\ref{lem:pauli-observable-expansion} gives
760		$\tau^W_a = \E_{b \in \F_q} (-1)^{\tr(ab)}\, \tau^W(b)$; writing
761		$b = \sum_j b_j e_j$, self-duality of the basis gives
762		$b_j = \tr(b e_j)$ (item 1 of Lemma~\ref{lem:downsize_field}) and hence
763		$\tr(ab) = \sum_j a_j b_j$. The product relation of
764		Lemma~\ref{lem:twisted-commutation} factors
765		$\tau^W(b) = \prod_j \tau^W(b_j e_j)$, so the expectation factors over
766		independent $b_1, \dots, b_k \in \F_2$. A computation on basis states shows
767		that for all $c \in \F_2$, $\tau^W(c e_j) = \theta^\dagger\,
768		\sigma^{W,j}(c)\, \theta$, where $\sigma^{W,j}(c)$ is the identity for
769		$c = 0$ and the Pauli $W$ observable acting on the $j$-th qubit of
770		$(\C^2)^{\ot k}$ for $c = 1$. Averaging,
771		$\E_{b_j \in \F_2} (-1)^{a_j b_j} \sigma^W(b_j) =
772		\frac{1}{2}\bigl(\Id + (-1)^{a_j}\sigma^W(1)\bigr) = \sigma^W_{a_j}$,
773		whence $\tau^W_a = \theta^\dagger \bigl(\bigotimes_j
774		\sigma^W_{a_j}\bigr) \theta$. Taking $\phi = \theta^{\ot L}$ and tensoring
775		the last identity over the $L$ qudits, using
776		$\tau^W_u = \bigotimes_{i=1}^L \tau^W_{u_i}$, yields both displayed
777		identities.
778	\end{proof}
