140	\begin{lemma}[Product form and Pauli relations of the pulled-apart observables]\label{lem:tildew-product-form}
141		\lean{MIPStarRE.QPBT.tildeObs_eq_heteroKron}
142		\lean{MIPStarRE.QPBT.tildeObs_isHermitian}
143		\lean{MIPStarRE.QPBT.tildeObs_mul_self}
