388	\begin{lemma}[Preservation of the robustness error family]\label{lem:qld-extraction-error-form}
389		\lean{MIPStarRE.QPBT.deltaExtract_le_deltaQld}
390		\uses{def:admissible, lem:qld-unitary}
391		Let $C\geq1$, $a>1$, and $0<b<1$. Suppose that
392		\[
393			\delta_G=a(md)^a\bigl(\eps^b+q^{-b}+2^{-bmd}\bigr),
394			\qquad
395			\delta_P=C\left(\delta_G+\sqrt{\eps}+\frac{md}{q}\right),
396		\]
397		and set $\delta_{\mathrm{ext}}=C(\delta_P^{1/4}+md/q)$. There are constants
398		$a'\geq1$ and $0<b'<1$, depending only on $C,a,b$, such that, for every
399		admissible $(q,m,d)$ and every $0\leq\eps\leq1$,
400		\[
401			\delta_{\mathrm{ext}}
402			\leq a'(md)^{a'}\bigl(\eps^{b'}+q^{-b'}+2^{-b'md}\bigr).
