477		\[
478			\bigl\| (\Id - Q_{\mathrm{A}}) \ket{\Delta} \bigr\|^2
479			= \bigl\| (\Id - Q_{\mathrm{A}}) (\ket{\Delta} - \ket{\vartheta}) \bigr\|^2
