484		\[
485			\bigl( \phi_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, \phi_{\mathrm{A}}^\dagger - (\tau^W_h)_{\mathrm{A}''} \bigr) \ket{\Delta}
