193	\begin{definition}[PCC and SPCC strategies]\label{def:spcc}
194		\lean{MIPStarRE.QPBT.Strategy.IsPCC, MIPStarRE.QPBT.SymmetricStrategy.IsSPCC}
195		\leanok
196		\uses{def:projective-strategy-general, def:consistent-strategy, def:comm-strategy, def:symmetric-game}
197		We say that a strategy $\mathcal S$ for a game $\mathfrak G$ is \emph{PCC} if it is projective, consistent, and commuting for $\mathfrak G$. Additionally, we say that a PCC strategy $\mathcal S$ is \emph{SPCC} if it is furthermore symmetric.
198	\end{definition}
